/// Single substitution suggestion generated by AI or culinary heuristics
class AiSubstitution {
  final String name;
  final String ratio;
  final String reason;
  final String? dietary;

  const AiSubstitution({
    required this.name,
    required this.ratio,
    required this.reason,
    this.dietary,
  });

  factory AiSubstitution.fromJson(Map<String, dynamic> json) {
    return AiSubstitution(
      name: json['name'] as String? ?? 'Substitute',
      ratio: json['ratio'] as String? ?? '1:1 ratio',
      reason: json['reason'] as String? ?? '',
      dietary: json['dietary'] as String?,
    );
  }

  Map<String, dynamic> toJson() => {
        'name': name,
        'ratio': ratio,
        'reason': reason,
        'dietary': dietary,
      };
}

/// Message exchanged in the interactive AI Chef Q&A session
class ChefChatMessage {
  final String id;
  final bool isUser;
  final String text;
  final bool? isAffirmative; // true for "Yes", false for "No", null for neutral
  final String? directVerdict; // "YES", "NO", "CAUTION"
  final DateTime timestamp;

  ChefChatMessage({
    String? id,
    required this.isUser,
    required this.text,
    this.isAffirmative,
    this.directVerdict,
    DateTime? timestamp,
  })  : id = id ?? const Uuid().v4(),
        timestamp = timestamp ?? DateTime.now();
}

/// Wrapper for substitution fetch result
class AiSubstitutionResult {
  final List<AiSubstitution> substitutions;
  final bool isLiveAi;
  final String? message;

  const AiSubstitutionResult({
    required this.substitutions,
    this.isLiveAi = true,
    this.message,
  });
}

class AiSubstitutionService {
  final OllamaClient _ollamaClient;

  AiSubstitutionService({required OllamaClient ollamaClient})
      : _ollamaClient = ollamaClient;

  /// Fetches context-aware substitutions from Ollama Cloud using the full recipe context
  Future<AiSubstitutionResult> getSubstitutions({
    required Recipe recipe,
    required Ingredient ingredient,
  }) async {
    final ingredientsSummary = recipe.ingredients
        .map((i) => '• ${i.fullDisplayText}')
        .join('\n');

    final stepsSummary = recipe.steps
        .map((s) => '${s.stepNumber}. ${s.instruction}')
        .join('\n');

    final prompt = '''
You are an expert chef assistant providing culinary substitutions for the recipe "${recipe.title}".

RECIPE INGREDIENTS:
$ingredientsSummary

RECIPE INSTRUCTIONS:
$stepsSummary

TARGET INGREDIENT TO SUBSTITUTE:
"${ingredient.name}" (Amount: ${ingredient.displayQuantity} ${ingredient.unit ?? ''}, Notes: ${ingredient.notes ?? 'none'})

TASK:
1. Examine the cooking technique (frying, baking, simmering, emulsifying, etc.) and role of "${ingredient.name}" in this specific recipe.
2. Recommend 3 to 4 smart, high-accuracy culinary substitutions that work with the flavor profile and cooking method.
3. For each substitution, provide:
   - "name": The substitute's standard culinary name (e.g. "Firm Tofu", "Greek Yogurt", "Silken Tofu Blend").
   - "ratio": How much to use (e.g. "1:1 swap", "Use 3/4 cup per 1 cup").
   - "reason": 1-2 practical sentences explaining how it behaves in this specific recipe and if any step timing needs adjusting.
   - "dietary": Dietary or nutritional highlight (e.g. "Vegan", "High-Protein", "Dairy-Free", "Low-Fat", "Gluten-Free").

Respond ONLY with valid JSON in this exact structure:
{
  "substitutions": [
    {
      "name": "Substitute Name",
      "ratio": "1:1 ratio",
      "reason": "Why it works with the recipe's cooking steps",
      "dietary": "Vegan"
    }
  ]
}
''';

    try {
      final response = await _ollamaClient.chat(
        messages: [
          {
            'role': 'system',
            'content':
                'You are an expert culinary assistant. Always respond strictly in valid JSON format.',
          },
          {'role': 'user', 'content': prompt},
        ],
        forceJsonFormat: true,
      );

      final decoded = jsonDecode(response.content) as Map<String, dynamic>;
      final rawList = decoded['substitutions'] as List<dynamic>? ?? [];

      final list = rawList
          .map((item) => AiSubstitution.fromJson(item as Map<String, dynamic>))
          .where((sub) => sub.name.trim().isNotEmpty)
          .toList();

      if (list.isNotEmpty) {
        return AiSubstitutionResult(substitutions: list, isLiveAi: true);
      }
    } catch (e) {
      AppLogger.info('AI Substitution generation fallback triggered: $e');
    }

    // Fallback to intelligent curated culinary substitutions if offline or API key missing
    final fallbacks = _getCulinaryFallbacks(ingredient.name);
    return AiSubstitutionResult(
      substitutions: fallbacks,
      isLiveAi: false,
      message: 'Showing culinary recommendations (Ollama offline/unconfigured)',
    );
  }

  /// Interactive Q&A with the AI Chef: asks a follow-up question and strictly formats a clear YES or NO
  Future<ChefChatMessage> askChefQuestion({
    required Recipe recipe,
    required Ingredient ingredient,
    required String question,
    List<ChefChatMessage> history = const [],
  }) async {
    final ingredientsSummary = recipe.ingredients
        .map((i) => '• ${i.fullDisplayText}')
        .join('\n');

    final stepsSummary = recipe.steps
        .map((s) => '${s.stepNumber}. ${s.instruction}')
        .join('\n');

    final systemPrompt = '''
You are an expert chef assistant helping someone cook "${recipe.title}".
Recipe Ingredients:
$ingredientsSummary

Recipe Instructions:
$stepsSummary

Target ingredient being substituted or asked about: "${ingredient.name}" (${ingredient.displayQuantity} ${ingredient.unit ?? ''}).

CRITICAL INSTRUCTION:
You MUST start your answer with a direct and unambiguous "YES" or "NO" (or "YES, WITH CAUTION:" / "NO, AVOID THIS:").
Following your direct YES/NO verdict, provide 1 to 3 concise, practical sentences explaining why, and give specific chef tips on adjusting cooking time, heat, or technique for this recipe. Keep it punchy, practical, and kitchen-focused.
''';

    final messages = <Map<String, String>>[
      {'role': 'system', 'content': systemPrompt},
    ];

    for (final h in history.take(6)) {
      messages.add({
        'role': h.isUser ? 'user' : 'assistant',
        'content': h.text,
      });
    }

    messages.add({'role': 'user', 'content': question});

    try {
      final response = await _ollamaClient.chat(
        messages: messages,
        forceJsonFormat: false,
      );

      final replyText = response.content.trim();
      final lower = replyText.toLowerCase();

      bool? isAffirmative;
      String? verdict;

      if (lower.startsWith('yes, with caution') || lower.startsWith('yes with caution')) {
        isAffirmative = true;
        verdict = 'YES, WITH CAUTION';
      } else if (lower.startsWith('yes')) {
        isAffirmative = true;
        verdict = 'YES';
      } else if (lower.startsWith('no')) {
        isAffirmative = false;
        verdict = 'NO';
      }

      return ChefChatMessage(
        isUser: false,
        text: replyText,
        isAffirmative: isAffirmative,
        directVerdict: verdict,
      );
    } catch (e) {
      AppLogger.info('Chef chat error: $e');
      return _generateOfflineChefAnswer(ingredient.name, question);
    }
  }

  /// Offline fallback answers for common culinary questions
  ChefChatMessage _generateOfflineChefAnswer(String ingredientName, String question) {
    final lowerQ = question.toLowerCase();
    final lowerName = ingredientName.toLowerCase();

    if (lowerQ.contains('omit') || lowerQ.contains('skip') || lowerQ.contains('without')) {
      if (lowerName.contains('garnish') || lowerName.contains('herb') || lowerName.contains('cilantro') || lowerName.contains('parsley')) {
        return ChefChatMessage(
          isUser: false,
          text: 'YES. You can safely omit it without affecting the core cooking chemistry or texture, though the fresh aromatic finish will be slightly subtler.',
          isAffirmative: true,
          directVerdict: 'YES',
        );
      }
      return ChefChatMessage(
        isUser: false,
        text: 'YES, WITH CAUTION. You can omit it, but you may need to compensate for the moisture or seasoning balance lost from removing it.',
        isAffirmative: true,
        directVerdict: 'YES, WITH CAUTION',
      );
    }

    if (lowerQ.contains('curdle') || lowerQ.contains('boil') || lowerQ.contains('split')) {
      return ChefChatMessage(
        isUser: false,
        text: 'NO, but add it off the heat or temper it first. Dairy substitutes like yogurt or low-fat milk curdle at high boiling temperatures, so stir them in gently after turning down the flame.',
        isAffirmative: false,
        directVerdict: 'NO',
      );
    }

    return ChefChatMessage(
      isUser: false,
      text: 'YES, in most cases with slight adjustment. Note: Ollama Cloud is currently offline; connect your API key in Settings for full real-time culinary AI reasoning.',
      isAffirmative: true,
      directVerdict: 'YES',
    );
  }

